{
  "name": "GNSS基准站接收机",
  "name_en": "GNSS Base Station Receiver",
  "manufacturer": "",
  "description": "GNSS基准站接收机用于接收卫星导航信号，提供位置估计、可见卫星、接收机状态和时间同步信息，并可记录原始观测数据。它常用于定位实验、基站配置管理、天线安装验证和授时测试。",
  "description_en": "A GNSS base station receiver acquires satellite navigation signals and provides position estimates, visible-satellite data, receiver status, and time-synchronization information. It is commonly used for positioning experiments, base-station configuration, antenna setup validation, and timing tests.",
  "tag_hints": [
    "GNSS base station",
    "satellite positioning",
    "raw observation logging",
    "time synchronization",
    "receiver status monitoring",
    "antenna configuration",
    "visible satellite tracking"
  ],
  "actions": [
    {
      "action_name": "auto-activeConfiguration",
      "description": "获取当前活动配置名称",
      "description_en": "Get the name of the active configuration."
    },
    {
