    },
    {
      "action_name": "auto-logRawData",
      "description": "获取原始GNSS数据记录状态",
      "description_en": "Get whether raw GNSS data logging is enabled."
    },
    {
      "action_name": "auto-logRawDataChanged",
      "description": "获取原始GNSS数据记录状态变更通知",
      "description_en": "Receive notification when the raw GNSS data logging setting changes."
    },
    {
      "action_name": "auto-posValidTimeout",
      "description": "获取位置有效超时时间",
      "description_en": "Get the position-valid timeout."
    },
    {
      "action_name": "auto-positionUpdate",
      "description": "获取新的位置信息更新",
      "description_en": "Receive new position information updates."
    },
    {
      "action_name": "auto-receiverInfo",
      "description": "获取接收机信息",
      "description_en": "Get receiver information."
    },
    {
      "action_name": "auto-restore",
      "description": "恢复已保存的设备属性",
      "description_en": "Restore saved device properties."
    },
    {
      "action_name": "auto-satelliteInfo",
      "description": "获取当前可见卫星信息",
      "description_en": "Get information about currently visible satellites."
    },
    {
      "action_name": "auto-satellitesChanged",
      "description": "获取可见卫星数量变更通知",
      "description_en": "Receive notification when the number of visible satellites changes."
    },
    {
      "action_name": "auto-save",
      "description": "保存设备属性",
      "description_en": "Save device properties."
    },
    {
      "action_name": "auto-saveConfig",
      "description": "保存当前配置到磁盘",
      "description_en": "Save the current configuration to disk."
    },
    {
      "action_name": "auto-setConfig",
      "description": "设置当前活动配置参数",
      "description_en": "Set the parameters of the active configuration."
    },
    {
      "action_name": "auto-setConfigDir",
      "description": "设置配置文件目录路径",
      "description_en": "Set the configuration directory path."
    },
    {
      "action_name": "auto-setDefConfig",
      "description": "设置默认配置",
      "description_en": "Set the default configuration."
    },
    {
      "action_name": "auto-setLogRawData",
      "description": "设置原始GNSS数据记录状态",
      "description_en": "Set whether raw GNSS data logging is enabled."
    },
    {
      "action_name": "auto-setPosValidTimeout",
      "description": "设置位置有效超时时间",
      "description_en": "Set the position-valid timeout."
    },
    {
      "action_name": "auto-setStorDir",
      "description": "设置原始数据存储目录路径",
      "description_en": "Set the raw-data storage directory path."
    },
    {
      "action_name": "auto-statusChanged",
      "description": "获取GNSS定位状态变更通知",
      "description_en": "Receive notification when the GNSS fix status changes."
    },
    {
      "action_name": "auto-storDir",
      "description": "获取原始数据存储目录路径",
      "description_en": "Get the raw-data storage directory path."
    },
    {
      "action_name": "auto-timeInfo",
      "description": "获取当前GNSS时间信息",
      "description_en": "Get current GNSS time information."
    },
    {
      "action_name": "auto-timesyncChanged",
      "description": "获取时间同步状态变更通知",
      "description_en": "Receive notification when the time synchronization status changes."
    },
    {
      "action_name": "auto-timesyncInfo",
      "description": "获取当前时间同步信息",
      "description_en": "Get current time synchronization information."
    },
    {
      "action_name": "auto-connected",
      "description": "获取设备连接状态变更通知",
      "description_en": "Receive notification when the device connection state changes."
    }
  ]
}

